import os
import sys
import unittest

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))

from textstats import summarize  # noqa: E402


class TestSummarize(unittest.TestCase):
    def test_empty_string(self):
        self.assertEqual(
            summarize(""),
            {"chars": 0, "words": 0, "lines": 0, "unique_words": 0},
        )

    def test_single_line(self):
        self.assertEqual(
            summarize("hello world"),
            {"chars": 11, "words": 2, "lines": 1, "unique_words": 2},
        )

