        self.assertEqual(
            summarize("a\nb\nc"),
            {"chars": 5, "words": 3, "lines": 3, "unique_words": 3},
        )

    def test_case_insensitive_uniqueness(self):
        result = summarize("The the THE")
        self.assertEqual(result["words"], 3)
        self.assertEqual(result["unique_words"], 1)

    def test_punctuation_not_stripped(self):
        result = summarize("hi, hi!")
        self.assertEqual(result["words"], 2)
        self.assertEqual(result["unique_words"], 2)

    def test_whitespace_only(self):
        result = summarize("   \n  ")
        self.assertEqual(result["words"], 0)
        self.assertEqual(result["unique_words"], 0)
        self.assertEqual(result["chars"], 6)

    def test_non_string_raises(self):
        with self.assertRaises(TypeError):
            summarize(123)


if __name__ == "__main__":
    unittest.main()

