    def test_basic_ordering(self):
        text = "apple banana apple cherry apple banana"
        self.assertEqual(top_words(text), [("apple", 3), ("banana", 2), ("cherry", 1)])

    def test_ties_broken_alphabetically(self):
        text = "beta alpha beta alpha gamma"
        self.assertEqual(top_words(text, n=2), [("alpha", 2), ("beta", 2)])

    def test_punctuation_stripped_and_case_folded(self):
        text = "Hello, hello! HELLO world."
        self.assertEqual(top_words(text, n=1), [("hello", 3)])

    def test_limit_n(self):
        text = "a b c d e"
        self.assertEqual(len(top_words(text, n=2)), 2)

    def test_n_non_positive(self):
        self.assertEqual(top_words("a b c", n=0), [])
