        self.assertEqual(result["chars"], 11)
        self.assertEqual(result["chars_no_ws"], 9)
        self.assertEqual(result["top_words"], [("two", 2), ("one", 1)])

    def test_empty(self):
        self.assertEqual(
            summarize(""),
            {"words": 0, "chars": 0, "chars_no_ws": 0, "top_words": []},
        )


